import { LitElement, html, type PropertyValues } from 'lit';
import { classMap } from 'lit/directives/class-map.js';
import { customElement } from 'lit/decorators/custom-element.js';
import { property } from 'lit/decorators/property.js';
import { provide } from '@lit/context';

import { getRandomId } from '@patternfly/pfe-core/functions/random.js';
import { InternalsController } from '@patternfly/pfe-core/controllers/internals-controller.js';
import { RovingTabindexController } from '@patternfly/pfe-core/controllers/roving-tabindex-controller.js';

import { RhTile, TileSelectEvent } from './rh-tile.js';
import { rhTileGroupContext, type RhTileGroupContext } from './context.js';

import { colorPalettes, type ColorPalette } from '@rhds/elements/lib/color-palettes.js';
import { themable } from '@rhds/elements/lib/themable.js';

import styles from './rh-tile-group.css' with { type: 'css' };

/**
 * A tile group organizes `\<rh-tile\>` elements into a selectable
 * set. When `radio` is set, it provides ARIA `role="radiogroup"`
 * and arrow-key navigation for screen readers. The group must
 * contain at least two tiles. Users should set `radio` when only
 * one option must be selected.
 *
 * @summary Groups tiles for checkbox or radio selection with
 *          keyboard navigation and form association.
 *
 */
@customElement('rh-tile-group')
@colorPalettes
@themable
export class RhTileGroup extends LitElement {
  static readonly styles = [styles];

  /**
   * Whether tile group interaction is disabled
   */
  @property({ type: Boolean, reflect: true }) disabled = false;

  /**
   * If tile is checkable, whether only one tile can be checked
   */
  @property({ type: Boolean, reflect: true }) radio = false;

  /**
   * Sets color palette, which affects the element's styles as well as descendants' color theme.
   * Overrides parent color context.
   * Your theme will influence these colors so check there first if you are seeing inconsistencies.
   * See [CSS Custom Properties](#css-custom-properties) for default values
   *
   * Tile group always resets its context to `base`, unless explicitly provided with a `color-palette`.
   */
  @property({ reflect: true, attribute: 'color-palette' }) colorPalette?: ColorPalette;

  #tiles: RhTile[] = [];

  @provide({ context: rhTileGroupContext })
  private groupContext: Readonly<RhTileGroupContext> = Object.freeze({
    disabled: false,
    radio: false,
  });

  #tabindex = RovingTabindexController.of(this, {
    getItems: () => this.#tiles,
  });

  #internals = InternalsController.of(this);

  /**
   * All slotted tiles
   */
  get tiles() {
    return this.#tiles;
  }

  /**
   * All selected tiles
   */
  get selected() {
    const selected = this.#tiles?.filter(tile=> tile.checked);
    const [first] = selected;
    return this.radio ? first : selected;
  }

  constructor() {
    super();
    this.addEventListener('select', this.#onSelect);
  }

  override connectedCallback() {
    super.connectedCallback();
    this.#updateGroupContext();
  }

  override firstUpdated(): void {
    this.updateItems();
  }

  override willUpdate(changed: PropertyValues<this>) {
    if (changed.has('disabled') || changed.has('radio')) {
      this.#updateGroupContext();
    }
    this.#internals.ariaDisabled = String(!!this.disabled);
    this.#internals.role = this.radio ? 'radiogroup' : null;
    let selected: RhTile | undefined;
    for (const tile of this.#tiles) {
      if (changed.has('radio')) {
        if (this.radio && !selected && tile.checked) {
          selected = tile;
        }
      }
    }
    if (changed.has('radio')) {
      this.selectItem(selected);
    }
  }

  render() {
    const { radio } = this;
    return html`
      <!-- Place \`rh-tile\` elements here. Each tile must have a
           headline slot with descriptive text for screen readers. -->
      <slot class="${classMap({ radio })}"
            @slotchange="${this.#onSlotchange}"></slot>
    `;
  }

  #updateGroupContext() {
    this.groupContext = Object.freeze({
      disabled: this.disabled,
      radio: this.radio,
    });
  }

  #selectTile(tileToSelect: RhTile, force?: boolean) {
    if (this.radio) {
      for (const tile of this.#tiles) {
        tile.checked = tile === tileToSelect;
      }
    } else {
      tileToSelect.checked = force ?? !tileToSelect.checked;
    }
  }

  #onSelect(event: Event) {
    if (event instanceof TileSelectEvent && this.#tiles.includes(event.target)) {
      if (this.disabled) {
        event.preventDefault();
        return false;
      } else {
        this.#selectTile(event.target, event.force);
      }
    }
  }

  /**
   * handles slot change by updating slotted tiles
   */
  #onSlotchange() {
    this.updateItems();
  }

  /** Sets focus on active tile */
  focus() {
    this.#tabindex.items[this.#tabindex.atFocusedItemIndex]?.focus();
  }

  /**
   * Programatically select a tile
   * @param tile tile to select
   */
  selectItem(tile?: RhTile) {
    if (tile) {
      this.#selectTile(tile);
    }
  }

  /**
   * Programatically toggle a tile
   * @param tile tile to toggle
   */
  toggleItem(tile?: RhTile) {
    if (tile?.checked) {
      tile.checked = false;
    } else {
      this.selectItem(tile);
    }
  }

  /** Updates slotted tiles and keyboard navigation. */
  updateItems() {
    // A descendant query is used instead of @queryAssignedElements so tiles can
    // be placed inside ordinary wrapper elements while still belonging to the group.
    const tiles = [...this.querySelectorAll('rh-tile')];

    this.#tiles = tiles;
    this.#tabindex.items = tiles;

    for (const tile of tiles) {
      tile.id ||= getRandomId('rh-tile');
    }
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'rh-tile-group': RhTileGroup;
  }
}
